// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);
        // setUp() deployed c with msg.sender == address(this), so this contract is owner.
        vm.deal(address(c), amount);
        uint256 receiverBefore = receiver.balance;
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        // General rule: any owner-authorized sendTo must credit the receiver with exactly `amount` wei.
        assertTrue(receiver.balance == receiverBefore + amount);
    }
}
